using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR; using Microsoft.Extensions.Options;
namespace JTradeERP.Application.Features.Security.ResetPassword;
public sealed class ResetPasswordHandler(IApplicationDbContext db,IPasswordService passwords,IClock clock,IOptions<SecurityOptions> options) : IRequestHandler<ResetPasswordCommand,ResetPasswordResponse>
{ public async Task<ResetPasswordResponse> Handle(ResetPasswordCommand r,CancellationToken ct){var user=db.Users.SingleOrDefault(x=>x.Email==r.Email.Trim()&&x.IsActive);if(user is null)throw new AuthenticationFailureException("Password reset could not be completed.");var now=clock.UtcNow;var challenge=db.PasswordResetOtps.Where(x=>x.UserId==user.Id&&x.UsedAt==null&&x.InvalidatedAt==null).OrderByDescending(x=>x.CreatedAt).FirstOrDefault();if(challenge is null||!challenge.IsUsable(now,options.Value.OtpMaxAttempts)){throw new AuthenticationFailureException("Password reset could not be completed.");}if(!passwords.Verify(challenge.OtpHash,r.Otp)){challenge.RecordFailure(options.Value.OtpMaxAttempts,now);await db.SaveChangesAsync(ct);throw new AuthenticationFailureException("Password reset could not be completed.");}challenge.Use(now);user.SetPasswordHash(passwords.Hash(r.NewPassword));foreach(var other in db.PasswordResetOtps.Where(x=>x.UserId==user.Id&&x.Id!=challenge.Id&&x.UsedAt==null&&x.InvalidatedAt==null).ToArray())other.Invalidate(now);foreach(var token in db.RefreshTokens.Where(x=>x.UserId==user.Id&&x.RevokedAt==null).ToArray())token.Revoke(now,"password-reset");db.Add(new SecurityAuditEntry(user.Id,"PasswordReset","User",user.Id.ToString(),null,"completed",Guid.NewGuid().ToString()));await db.SaveChangesAsync(ct);return new("Password reset completed.");} }
